 @SuppressWarnings("unchecked")private static void effects(boolean enabled){var map=queues();if(!enabled){NativePropulsionTicks.installClient(owner->{});hidden=map.remove(NativePropulsionParticleRenderType.INSTANCE);need(hidden instanceof Queue<?> queue&&!queue.isEmpty(),"actual native particle-engine queue exists");try{((Queue<net.minecraft.client.particle.Particle>)pending.get(Minecraft.getInstance().particleEngine)).removeIf(p->p.getRenderType()==NativePropulsionParticleRenderType.INSTANCE);}catch(ReflectiveOperationException failure){throw new IllegalStateException(failure);}}else{map.put(NativePropulsionParticleRenderType.INSTANCE,(Queue<net.minecraft.client.particle.Particle>)hidden);hidden=null;NativePropulsionTicks.installClient(NativePropulsionParticles::tick);}}
